<script lang="ts">
 import {onMount} from 'svelte';
 type Calibration={experiment_hash:string;admission_id:string;dataset_hash:string;profile_hash:string;code_revision:string;training_start_ns:number;training_end_ns:number;evaluation_policy:string;diagnostic_artifact_hash:string;estimate_hash:string};
 type Prospective={job_id:string;admission_id:string;evaluation_policy:string;dataset_hash:string;profile_hash:string;code_revision:string;start_ns:number;end_ns:number};
 type Inputs={calibration:Calibration[];prospective:Prospective[];scope?:string};
 type Report={cohort_id:string;schema_version:string;historical:boolean;source_current:boolean;selected_count:number;native_observed:number;audit_complete:boolean;prospective_rejections_audited:number;false_negatives:number;known_counterexamples:number;disposition:string;approximate_pruning_authorized:boolean;descriptive_wilson_95:unknown;limitations:string[]};
 let {request,download}:{request:(path:string,method?:string,body?:unknown)=>Promise<any>;download:(path:string,name:string)=>Promise<void>}=$props();
 const ATTESTATION='Freeze this historical training-only calibration cohort before prospective native outcomes; reviewed admission only, no approximate pruning or validation authority';
 let inputs=$state<Inputs>({calibration:[],prospective:[]}),cohorts=$state<{cohort_id:string}[]>([]),report=$state<Report|null>(null),error=$state(''),busy=$state(false);
 let calibration=$state<string[]>([]),prospective=$state<string[]>([]),actor=$state(''),attest=$state(false),sample=$state(1),seed=$state(42),offset=$state(0);
 const ATTEMPTED_OTHER_VERSION='Selected inputs do not share one reviewed admission/profile/dataset/code revision.';
 const policy=()=>{const item=inputs.calibration.find((row)=>calibration.includes(row.experiment_hash));return item?{admission_id:item.admission_id,profile_hash:item.profile_hash,dataset_hash:item.dataset_hash,code_revision:item.code_revision,training_start_ns:item.training_start_ns,training_end_ns:item.training_end_ns}:null;};
 const consistent=()=>{const selected=inputs.prospective.filter((row)=>prospective.includes(row.job_id));const base=policy();if(!base||selected.length===0)return false;return selected.every((row)=>row.admission_id===base.admission_id&&row.profile_hash===base.profile_hash&&row.dataset_hash===base.dataset_hash&&row.code_revision===base.code_revision)&&selected.every((row)=>row.start_ns>=base.training_end_ns+86400*10**9);};
 async function refresh(){try{inputs=await request('research/historical-screen-cohort-inputs?limit=50&offset='+offset);cohorts=(await request('research/screen-cohorts?limit=20&offset='+offset)).cohorts;error='';}catch(e){error=String(e);}}
 onMount(refresh);
 async function inspect(id:string){try{report=await request('research/screen-cohorts/'+id);error='';}catch(e){error=String(e);}}
 async function freeze(event:SubmitEvent){event.preventDefault();busy=true;try{const base=policy();if(!base||!consistent())throw new Error(ATTEMPTED_OTHER_VERSION);const result=await request('research/historical-screen-cohorts','POST',{policy:base,calibration_experiments:calibration,prospective_job_ids:prospective,audit_sample_count:sample,seed,authorized_by:actor,attestation:ATTESTATION});await refresh();await inspect(result.cohort_id);}catch(e){error=String(e);}finally{busy=false;}}
 async function page(delta:number){offset=Math.max(0,offset+delta);calibration=[];prospective=[];await refresh();}
</script>
<section class="cohorts" aria-label="Historical prospective calibration cohorts">
 <header><h2>Historical prospective calibration cohorts</h2><button onclick={refresh} disabled={busy}>Refresh historical cohorts</button></header>
 <p>Freeze reviewed-admission historical calibration and a prospective audit frame before native outcomes. Version 2 requires reviewed admission, exact profile/dataset/code binding, a 24h post-calibration embargo and an explicit no-pruning attestation. Approximate labels cannot prune candidates or qualify strategies.</p>
 {#if inputs.scope}<p class="scope">{inputs.scope}</p>{/if}
 {#if error}<p role="alert">{error}</p>{/if}
 <form onsubmit={freeze}>
  <fieldset><legend>Retained historical calibration diagnostics</legend>{#each inputs.calibration as item}<label class="choice"><input type="checkbox" bind:group={calibration} value={item.experiment_hash}/><span>{item.admission_id.slice(0,12)} · {item.evaluation_policy}<small>{item.experiment_hash} · {item.training_start_ns}..{item.training_end_ns} · diagnostic {item.diagnostic_artifact_hash.slice(0,12)}</small></span></label>{/each}{#if inputs.calibration.length===0}<p>No current-source reviewed-admission historical diagnostic evidence.</p>{/if}</fieldset>
  <fieldset><legend>Prospective sampling frame</legend>{#each inputs.prospective as item}<label class="choice"><input type="checkbox" bind:group={prospective} value={item.job_id}/><span>{item.admission_id.slice(0,12)} · {item.evaluation_policy}<small>{item.job_id} · {item.start_ns}..{item.end_ns}</small></span></label>{/each}{#if inputs.prospective.length===0}<p>No unattempted reviewed-admission historical jobs.</p>{/if}</fieldset>
  <p>The frozen policy binds reviewed admission, exact profile, canonical dataset, current code revision and calibration coverage. Prospective training must start at least 24 hours after calibration ends. Already attempted, previously sampled, quarantined, protected or influenced periods are rejected. Membership stays immutable.</p>
  <div class="fields"><label>Audit sample size <input type="number" min="1" max="128" bind:value={sample} required/></label><label>Audit seed <input type="number" min="0" step="1" bind:value={seed} required/></label><label>Cohort authorized by <input bind:value={actor} maxlength="200" required/></label></div>
  <label class="choice"><input type="checkbox" bind:checked={attest}/><span>{ATTESTATION}</span></label>
  <button disabled={busy||!attest||!calibration.length||prospective.length<sample||!consistent()}>Freeze historical cohort</button>
  {#if calibration.length&&prospective.length&&!consistent()}<p role="alert">{ATTEMPTED_OTHER_VERSION} Prospective training must also start at least 24h after calibration ends.</p>{/if}
 </form>
 <nav aria-label="Historical cohort input pages"><button disabled={offset===0||busy} onclick={()=>page(-20)}>Previous cohort inputs</button><span>Offset {offset}</span><button disabled={busy} onclick={()=>page(20)}>Next cohort inputs</button></nav>
 <h3>Retained cohorts</h3>{#each cohorts as cohort}<button class="identity" onclick={()=>inspect(cohort.cohort_id)}>{cohort.cohort_id}</button>{/each}{#if cohorts.length===0}<p>No cohorts frozen on this page.</p>{/if}
 {#if report}<article><h3>Native audit feedback</h3><p>{report.disposition.replaceAll('_',' ').toLowerCase()}</p><p>{report.native_observed} / {report.selected_count} selected native observations · {report.audit_complete?'complete':'incomplete'}</p><p>{report.false_negatives} false negatives / {report.prospective_rejections_audited} prospective rejections audited</p><p>{report.known_counterexamples} known calibration/audit counterexamples. Approximate pruning: {report.approximate_pruning_authorized?'authorized':'disabled'}.</p><p>Source revision: {report.source_current?'current':'retained older revision'}</p><p>Descriptive Wilson 95% interval: {report.descriptive_wilson_95?JSON.stringify(report.descriptive_wilson_95):'no rejected audit observations'}</p><ul>{#each report.limitations as limitation}<li>{limitation}</li>{/each}</ul><button onclick={()=>inspect(report!.cohort_id)}>Refresh native audit feedback</button><button onclick={()=>download('research/screen-cohorts/'+report!.cohort_id,'historical-screen-cohort-'+report!.cohort_id+'.json')}>Export exact cohort evidence</button></article>{/if}
</section>
<style>
 .cohorts{margin:1.2rem 0;padding:1rem;background:#151e29;border:1px solid #304158;border-radius:12px;overflow-wrap:anywhere}header,.fields,nav{display:flex;flex-wrap:wrap;gap:.8rem;align-items:center;justify-content:space-between}fieldset{min-width:0;margin:1rem 0;border:1px solid #40516a;border-radius:8px}.choice{display:flex;align-items:flex-start;gap:.6rem;margin:.6rem 0}.choice input{width:auto;flex:none}small{display:block;color:#b5c2d3}.fields label{flex:1;min-width:180px}input{display:block;max-width:100%;box-sizing:border-box;padding:.6rem}.identity{display:block;overflow-wrap:anywhere;max-width:100%;margin:.5rem 0;text-align:left}article{margin-top:1rem}.scope{color:#b5c2d3}button{padding:.6rem;margin:.2rem;max-width:100%}
</style>
